from pathlib import Path
import json
p=next(Path.cwd().iterdir());names=[('观照之门','认识自己，向内探索'),('三境同生','生命、身体、心智协调成长'),('知行之页','智慧学习，日常实践'),('东方新印','东方文化，现代传承'),('身心相和','安顿身心，互补平衡'),('日日精进','持续练习，逐步成长'),('内在明镜','看见自己，清晰觉察'),('归心之所','安心停留，温和陪伴'),('启明','智慧启发，找到方向'),('一念入静','禅修专注，回到当下'),('生命根脉','认识生命，扎根成长'),('相遇同行','可信老师，学习伙伴'),('慧行','智慧与行动相结合'),('松弛有度','觉察身体，日常调养'),('问而有路','智能助伴，理解困惑'),('三阶成长','认识、修复、提升自己'),('中和','东方平衡，身心协调'),('可回之处','可以随时回到的陪伴'),('展卷','可信内容，自主学习'),('成长留痕','日常记录，长期积累')]
(p/'02_需求与设计参考/Logo20款编号与含义.json').write_text(json.dumps([{'number':f'{i+1:02d}','name':n,'meaning':m} for i,(n,m) in enumerate(names)],ensure_ascii=False,indent=2),encoding='utf-8')
cards=''.join(f'<article class="card" data-id="{i+1:02d}"><button class="art" data-open="{i+1:02d}" aria-label="放大{i+1:02d} {n}"><img src="Logo20款-{i+1:02d}.png" alt="{n}Logo候选"></button><div class="caption"><span class="num">{i+1:02d}</span><div><h2>{n}</h2><p>{m}</p></div><button class="pick" aria-pressed="false" aria-label="选择{i+1:02d}">☆</button></div></article>' for i,(n,m) in enumerate(names))
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>东方智慧 · 20款极简Logo对比</title><style>*{box-sizing:border-box}body{margin:0;background:#f0f1ed;color:#28483e;font-family:'Microsoft YaHei',sans-serif}.wrap{max-width:1600px;margin:auto;padding:35px 35px 28px}header{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:24px}header small{font:10px Consolas;letter-spacing:2px;color:#6c7f71}h1{font:500 29px 'Microsoft YaHei';margin:9px 0 10px}header p{font-size:12px;color:#617466;line-height:1.8;margin:0}.selected{font-size:12px;line-height:1.8;color:#617466;max-width:340px;text-align:right;min-height:24px}.grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:17px}.card{min-width:0;background:white;border:1px solid #dce2d9;border-radius:7px;overflow:hidden}.card.chosen{outline:2px solid #365f4d;outline-offset:1px}.art{display:block;border:0;background:white;padding:0;width:100%;aspect-ratio:1;cursor:zoom-in}.art img{width:100%;height:100%;object-fit:contain;display:block}.caption{display:flex;align-items:center;gap:10px;padding:13px 12px 15px;border-top:1px solid #eef0eb;min-height:76px}.num{font:22px Georgia;color:#879c8c}.caption>div{flex:1;min-width:0}.caption h2{font-size:13px;font-weight:500;margin:0 0 7px}.caption p{font-size:9px;line-height:1.6;color:#6b7d70;margin:0}.pick{border:0;background:none;color:#56775f;font-size:23px;cursor:pointer;padding:5px}.pick[aria-pressed=true]{color:#a17a3a}.foot{margin:22px 0 0;font-size:10px;color:#6b7d70;line-height:1.9}dialog{width:min(700px,92vw);border:1px solid #ccd5cb;border-radius:12px;padding:16px;background:white;color:#28483e}dialog::backdrop{background:#11291ee0}dialog img{display:block;width:100%;max-height:70vh;object-fit:contain}dialog .bar{display:flex;justify-content:space-between;align-items:center;font-size:14px;padding:4px 8px}dialog button{border:1px solid #cbd7cc;padding:9px 16px;background:#edf2eb;border-radius:6px;cursor:pointer}button:focus-visible{outline:3px solid #b28d45;outline-offset:2px}@media(max-width:1000px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.wrap{padding:22px}header{display:block}.selected{text-align:left;margin-top:12px}}@media(max-width:600px){.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.wrap{padding:16px}h1{font-size:23px}.caption{padding:10px 8px;gap:7px}.num{font-size:18px}.caption h2{font-size:12px}.caption p{font-size:8px}.pick{font-size:20px}}</style><div class="wrap"><header><div><small>EASTERN WISDOM / BRAND MARK STUDIES</small><h1>东方智慧 · 20 款极简 Logo</h1><p>围绕产品理念重新构思 · 统一单色，集中比较造型与含义 · 点击放大，星标暂选</p></div><div class="selected" role="status">尚未暂选</div></header><main class="grid">'''+cards+'''</main><p class="foot">候选概念图 · 生成位图，非最终矢量定稿 · 第19款只作为简洁程度参考，不作为造型模板。编号对应本轮20款，与原PDF编号无关。</p></div><dialog><div class="bar"><span></span><button class="close">关闭</button></div><img alt="放大Logo"></dialog><script>const chosen=new Set(),dlg=document.querySelector('dialog');document.addEventListener('click',e=>{const p=e.target.closest('.pick');if(p){const c=p.closest('.card'),id=c.dataset.id;chosen.has(id)?chosen.delete(id):chosen.add(id);const yes=chosen.has(id);p.setAttribute('aria-pressed',yes);p.textContent=yes?'★':'☆';c.classList.toggle('chosen',yes);document.querySelector('.selected').textContent=chosen.size?'暂选：'+[...chosen].sort().join('、'):'尚未暂选';return}const b=e.target.closest('[data-open]');if(b){const c=b.closest('.card');dlg.querySelector('img').src=b.querySelector('img').src;dlg.querySelector('.bar span').textContent=c.dataset.id+' · '+c.querySelector('h2').textContent;dlg.showModal()}if(e.target.closest('.close')||e.target===dlg)dlg.close()});</script></html>'''
(p/'02_需求与设计参考/Logo20款对比挑选.html').write_text(html,encoding='utf-8');print('20 numbered concepts and interactive comparison layout prepared.')
